                arabicText = "فِي يَوْمِ الْجُمُعَةِ سَاعَةٌ، لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ، وَهُوَ قَائِمٌ يُصَلِّي، يَسْأَلُ اللَّهَ تَعَالَى شَيْئًا، إِلَّا أَعْطَاهُ إِيَّاهُ، وَأَشَارَ بِيَدِهِ يُقَلِّلُهَا ۝ هِيَ مَا بَيْنَ أَنْ يَجْلِسَ الْإِمَامُ إِلَى أَنْ تُقْضَى الصَّلَاةُ ۝ يَوْمُ الْجُمُعَةِ اثْنَتَا عَشْرَةَ سَاعَةً، لَا يُوجَدُ فِيهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ شَيْئًا إِلَّا آتَاهُ إِيَّاهُ، فَالْتَمِسُوهَا آخِرَ سَاعَةٍ بَعْدَ الْعَصْرِ",
                pronunciationBn = "ফী ইয়াওমিল জুমু‘আতি সা-‘আতুন, লা- ইউওয়া-ফিক্বুহা- ‘আবদুম মুসলিমুন, ওয়াহুওয়া ক্বা-ইমুন ইউসাল্লী, ইয়াসআলুল্লা-হা তা‘আ-লা- শাইআন, ইল্লা- আ‘ত্বা-হু ইয়্যা-হু, ওয়া আ-শা-রা বিয়াদিহী ইউক্বাললিলুহা-... হিয়া মা- বায়নাহ আন ইয়াজলিসাল ইমা-মু ইলা- আন তুক্বদ্বাস সালা-হ... ফালতামিসূহা- আ-খিরা সা-‘আতিম বা‘দাল ‘আসর।",
                meaningBn = "আবূ হুরায়রা (রাঃ) থেকে বর্ণিত, রাসূলুল্লাহ ﷺ জুম্মার দিনের কথা উল্লেখ করে বললেন: ‘এই দিনে এমন একটি সময় আছে, যে সময়ে কোনো মুসলিম বান্দা দাঁড়িয়ে সালাত আদায় করে আল্লাহর কাছে কিছু চাইলে, আল্লাহ তাকে অবশ্যই তা দান করেন।’ তিনি ﷺ হাত দিয়ে ইশারা করে বোঝালেন যে সেই সময়টি খুবই সংক্ষিপ্ত।\n\nসময়টি কখন? সহীহ হাদিসের আলোকে সবচেয়ে শক্তিশালী দুটি মত:\n১. প্রথম মত (সবচেয়ে জোরালো): জাবির ইবনে আব্দুল্লাহ (রাঃ) থেকে বর্ণিত, রাসূলুল্লাহ ﷺ বলেছেন: ‘জুম্মার দিন বারো ঘণ্টার। এর মধ্যে এমন একটি মুহূর্ত আছে যখন কোনো মুসলিম আল্লাহর কাছে কিছু চাইলে আল্লাহ তাকে তা অবশ্যই দেন। তোমরা আসরের পরের শেষ সময়ে (সূর্যাস্তের পূর্বে) তা তালাশ করো।’ (আবু দাউদ: ১০৪৮; নাসাঈ: ১৩৮৯)।\n২. দ্বিতীয় মত: আবু মূসা আল-আশ'আরী (রাঃ) বলেন, রাসূলুল্লাহ ﷺ বলেছেন: ‘(দোয়া কবুলের) সেই সময়টি হলো ইমামের (মিম্বরে) বসা থেকে সালাত শেষ হওয়া পর্যন্ত।’ (সহীহ মুসলিম: ৮৫৩)।\n\nইমাম ইবনুল কাইয়িম (রহঃ)-এর সমন্বয়মূলক মত ('যাদুল মা'আদ'): উভয় সময়ই দোয়া কবুলের অত্যন্ত জোরালো সময়। তাই উভয় মুহূর্তেই দো'আয় মশগুল হওয়া বুদ্ধিমানের কাজ।",
                fojilotBn = "📖 হাদিস বিশারদদের তাহকীক ও সালাতরত থাকার ব্যাখ্যা:\nমুহাদ্দিসীনগণ ব্যাখ্যা করেছেন: সালাতরত থাকার অর্থ— ওজু সহকারে বসে সালাতের অপেক্ষায় থাকা কিংবা তাসবীহ ও দোয়ায় মশগুল থাকা। কারণ রাসূলুল্লাহ ﷺ বলেছেন, ‘যে ব্যক্তি সালাতের অপেক্ষায় বসে থাকে, সে সালাতরত অবস্থাতেই পরিগণিত হয়।’ (সহীহ বুখারী)।",
